css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .5); display: flex; gap: calc(var(--loader-size) * .015); perspective: 300px; }
.loader span { flex: 1; background: #f8fafc; border-radius: 0 0 5px 5px; transform-origin: top center; box-shadow: inset 0 -4px 6px rgba(0, 0, 0, .12); animation: press calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader span:nth-child(1) { animation-delay: 0s; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .12); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .24); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .48); }
@keyframes press { 0%, 100% { transform: rotateX(0deg); background: #f8fafc; } 50% { transform: rotateX(30deg); background: linear-gradient(var(--accent), var(--accent-2)); } }
